CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{"auto_save":false}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_finance_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'name', NEW.raw_user_meta_data->>'full_name', '')); RETURN NEW; END; $$;
CREATE TRIGGER create_finance_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_finance_profile();
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, file_path text NOT NULL, original_filename text NOT NULL, mime_type text NOT NULL CHECK (mime_type IN ('image/jpeg','image/png','image/webp','application/pdf')), file_size bigint NOT NULL CHECK (file_size > 0 AND file_size <= 20971520), document_type text NOT NULL DEFAULT 'Não identificado', issuer text, document_date date, due_date date, total_amount numeric(14,2), extracted_text text, extraction_confidence numeric, processing_status text NOT NULL DEFAULT 'archived' CHECK (processing_status IN ('archived','queued','processing','review','completed','error')), notes text NOT NULL DEFAULT '', favorite boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id,file_path));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.documents TO authenticated;
GRANT ALL ON public.documents TO service_role;
ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_owner ON public.documents FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND split_part(file_path,'/',1) = auth.uid()::text);
CREATE INDEX documents_owner_date ON public.documents(user_id,created_at DESC);
CREATE TABLE public.expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, document_id uuid REFERENCES public.documents(id), description text NOT NULL, category text, expense_date date NOT NULL, due_date date, payment_date date, total_amount numeric(14,2) NOT NULL CHECK (total_amount >= 0), paid_amount numeric(14,2) NOT NULL DEFAULT 0 CHECK (paid_amount >= 0), payment_status text NOT NULL DEFAULT 'Pendente', beneficiary_type text NOT NULL DEFAULT 'Pendente de classificação', allocation_percentage numeric(5,2) CHECK (allocation_percentage BETWEEN 0 AND 100), allocated_amount numeric(14,2), allocation_method text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.expenses TO authenticated;
GRANT ALL ON public.expenses TO service_role;
ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;
CREATE POLICY expenses_owner ON public.expenses FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND (document_id IS NULL OR EXISTS (SELECT 1 FROM public.documents d WHERE d.id = document_id AND d.user_id = auth.uid())));
CREATE INDEX expenses_owner_date ON public.expenses(user_id,expense_date);
CREATE POLICY private_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'financial-documents' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY private_files_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'financial-documents' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY private_files_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'financial-documents' AND (storage.foldername(name))[1] = auth.uid()::text);